namespace sv_b92e8f08871a4e898cd73dc4c8941353.Client.Models;

public sealed record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateOnly EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public sealed record StatusUpdate(
    DateTime Timestamp,
    string Status,
    string Location);

using sv_b92e8f08871a4e898cd73dc4c8941353.Client.Models;

namespace sv_b92e8f08871a4e898cd73dc4c8941353.Client.Services;

public interface IShipmentService
{
    Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using sv_b92e8f08871a4e898cd73dc4c8941353.Client.Models;
using sv_b92e8f08871a4e898cd73dc4c8941353.Client.Services;

namespace sv_b92e8f08871a4e898cd73dc4c8941353.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> Seeds = new(StringComparer.OrdinalIgnoreCase)
    {
        ["PKG-001"] = new Shipment(
            "PKG-001",
            "In Transit",
            "Memphis, TN",
            DateOnly.FromDateTime(DateTime.Today.AddDays(2)),
            [
                new StatusUpdate(DateTime.UtcNow.AddDays(-3), "Picked Up", "New York, NY"),
                new StatusUpdate(DateTime.UtcNow.AddDays(-2), "In Transit", "Philadelphia, PA"),
                new StatusUpdate(DateTime.UtcNow.AddDays(-1), "In Transit", "Memphis, TN"),
            ]),

        ["PKG-002"] = new Shipment(
            "PKG-002",
            "Delivered",
            "San Francisco, CA",
            DateOnly.FromDateTime(DateTime.Today.AddDays(-1)),
            [
                new StatusUpdate(DateTime.UtcNow.AddDays(-5), "Picked Up", "Seattle, WA"),
                new StatusUpdate(DateTime.UtcNow.AddDays(-3), "In Transit", "Portland, OR"),
                new StatusUpdate(DateTime.UtcNow.AddDays(-1), "Delivered", "San Francisco, CA"),
            ]),

        ["PKG-003"] = new Shipment(
            "PKG-003",
            "Processing",
            "Chicago, IL",
            DateOnly.FromDateTime(DateTime.Today.AddDays(5)),
            [
                new StatusUpdate(DateTime.UtcNow.AddHours(-6), "Label Created", "Chicago, IL"),
                new StatusUpdate(DateTime.UtcNow.AddHours(-2), "Processing", "Chicago, IL"),
            ]),
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        Seeds.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_b92e8f08871a4e898cd73dc4c8941353.Client.Models
@using sv_b92e8f08871a4e898cd73dc4c8941353.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracking</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p>@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm mt-2" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.ToString("D")</p>
        </div>
    </div>

    <h5>Status Updates</h5>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Timestamp</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.Updates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = string.Empty;

    private Shipment? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override Task OnParametersSetAsync() => LoadShipmentAsync();

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request when the tracking number changes or on retry.
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed — silently stop.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error fetching shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

